export type ParsedAgentChallengeInstruction<
  TProgram extends string = typeof DEAL_ESCROW_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    agent: TAccountMetas[0];
    mission: TAccountMetas[1];
    mandate: TAccountMetas[2];
    missionAuth: TAccountMetas[3];
    deal: TAccountMetas[4];
    mint: TAccountMetas[5];
    dealVault: TAccountMetas[6];
    vault: TAccountMetas[7];
    tokenProgram: TAccountMetas[8];
    dealProgram: TAccountMetas[9];
  };
  data: AgentChallengeInstructionData;
};

export function parseAgentChallengeInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedAgentChallengeInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 10) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 10,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      agent: getNextAccount(),
      mission: getNextAccount(),
      mandate: getNextAccount(),
      missionAuth: getNextAccount(),
      deal: getNextAccount(),
      mint: getNextAccount(),
      dealVault: getNextAccount(),
      vault: getNextAccount(),
      tokenProgram: getNextAccount(),
      dealProgram: getNextAccount(),
    },
    data: getAgentChallengeInstructionDataDecoder().decode(instruction.data),
  };
}
